"""Raw-only atlas, contact signatures, and an offline interactive raw/fitted viewer."""
import argparse,json,os
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/pilgrim_harvest_mpl')
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main(p):
 run=json.loads((p/'run.json').read_text());d=json.loads((p/'skeleton.json').read_text());analysis=json.loads((p/'analysis.json').read_text());scale=run['normalized_units_per_design_meter'];atlas=p/'atlas';atlas.mkdir(exist_ok=True);data=[]
 for r in analysis['results']:
  name=r['name'];raw=np.load(p/(name+'.xyz.npy'))/scale+[0,.06,0];fit=np.load(p/(name+'.fitted.xyz.npy'))/scale+[0,.06,0];data.append(dict(name=name,raw=raw.round(5).tolist(),fitted=fit.round(5).tolist(),metrics=r))
 for page in range((len(data)+11)//12):
  fig,axs=plt.subplots(3,4,figsize=(16,12));fig.suptitle('MOTION HARVEST 001 / raw unguided phrases / sheet '+str(page+1),fontsize=18)
  for ax,c in zip(axs.flat,data[page*12:page*12+12]):
   x=np.array(c['raw']);m=c['metrics'];col=['#c8d9d8','#91b4b3','#55908f','#22615f']
   for f,color in zip([0,19,39,59],col):
    pose=np.c_[x[f,:,0]+.4*x[f,:,2],x[f,:,1]]
    for j,pa in enumerate(d['parents']):
     if pa>=0:ax.plot(*pose[[pa,j]].T,c=color,lw=1.3)
   ax.axhline(0,c='#999999',lw=.5);ax.set_aspect('equal');ax.set_xlim(-1.6,1.8);ax.set_ylim(-.35,3.6);ax.set_title(c['name'].replace('Pilgrim_','')+'\nfit RMS %.3f · pitch %.1f° · yaw %.1f°'%(m['fit_rms'],m['raw']['torso_pitch_range_degrees'],m['raw']['torso_yaw_range_degrees']),fontsize=10);ax.set_axis_off()
  for ax in list(axs.flat)[len(data[page*12:page*12+12]):]:ax.set_visible(False)
  fig.text(.5,.02,'Light to dark: frames 1, 20, 40, 60. Display is an oblique projection; no cleanup or invented action labels.',ha='center',fontsize=11);fig.tight_layout(rect=[0,.035,1,.955]);fig.savefig(atlas/('raw_sheet_%02d.png'%(page+1)),dpi=120);plt.close(fig)
 template='''<!doctype html><meta charset="utf-8"><title>Pilgrim · Motion Harvest 001</title><style>body{margin:0;background:#172126;color:#e3e5df;font:15px system-ui}header{padding:22px 28px;background:#243239}h1{margin:0 0 8px;font-size:26px}main{padding:20px;display:grid;grid-template-columns:310px 1fr;gap:20px}select,button,input{font:inherit;margin:5px;padding:7px;background:#30434b;color:#fff;border:1px solid #657777}select{width:290px}canvas{width:100%;background:#202d33;border-radius:8px}pre{white-space:pre-wrap;font-size:13px;line-height:1.6}small{color:#b3c2c2}.tag{color:#e0bf78}#metrics{max-height:650px;overflow:auto}@media(max-width:800px){main{display:flex;flex-direction:column;padding:12px}section{order:-1}select{max-width:95%}header{padding:16px}h1{font-size:22px}}label{display:block}</style><header><h1>Motion Harvest 001</h1><div>120 unguided three-second samples · raw and fitted views · no behavioral names assigned by the viewer</div><small>Contact bars are height/speed candidates, not measured load. Colors match limb A/B/C/D. Space pauses playback.</small></header><main><aside><label>Sample<select id="samples"></select></label><button id="play">Pause</button><label>Frame<input id="frame" type="range" min="0" max="59" value="0"></label><label>View angle<input id="angle" type="range" min="-180" max="180" value="25"></label><label>Speed<select id="speed"><option value="1">Native 20 fps</option><option value="0.5">Half speed (display only)</option></select></label><pre id="metrics"></pre></aside><section><canvas id="view" width="1300" height="780"></canvas><p class="tag">Left: original model joint positions. Right: fixed-length reconstruction. Neither view has contact correction.</p><pre id="signature"></pre></section></main><script>const data=DATA,parents=PARENTS,names=NAMES;const sel=document.querySelector('#samples'),cv=document.querySelector('#view'),ctx=cv.getContext('2d'),slider=document.querySelector('#frame');let index=0,frame=0,playing=true,last=0;data.forEach((d,i)=>{let o=document.createElement('option');o.value=i;o.textContent=d.name.replace('Pilgrim_','');sel.append(o)});function select(){index=+sel.value;let d=data[index],r=d.metrics.raw;document.querySelector('#metrics').textContent=JSON.stringify({fit_rms:d.metrics.fit_rms,root_height_change:r.root_height_change,torso_pitch_range:r.torso_pitch_range_degrees,torso_yaw_range:r.torso_yaw_range_degrees,head_displacement:r.head_displacement,support_transitions:r.support_transitions,displacement:r.overall_displacement,acceleration_p95:r.joint_acceleration_p95,asymmetry:r.asymmetry,contact_threshold_agreement:r.contact_threshold_agreement},null,2);document.querySelector('#signature').textContent=r.contact_signature.join('\\n');}sel.onchange=select;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};window.onkeydown=e=>{if(e.code==='Space'){e.preventDefault();document.querySelector('#play').click()}};slider.oninput=()=>frame=+slider.value;function draw(t){if(playing){let step=50/+document.querySelector('#speed').value,n=Math.floor((t-last)/step);if(n>0){frame=(frame+n)%60;slider.value=frame;last+=n*step}}else last=t;ctx.clearRect(0,0,1300,780);ctx.font='24px system-ui';ctx.fillStyle='#dbe4df';ctx.fillText('RAW / '+(frame+1),45,45);ctx.fillText('FITTED / '+(frame+1),690,45);let angle=+document.querySelector('#angle').value*Math.PI/180;for(let side=0;side<2;side++){let x=data[index][side?'fitted':'raw'][frame],cx=325+650*side;let project=v=>[cx+(v[0]*Math.cos(angle)+v[2]*Math.sin(angle))*175,685-v[1]*175];ctx.strokeStyle='#52636a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(side*650+20,685);ctx.lineTo(side*650+630,685);ctx.stroke();for(let j=1;j<x.length;j++){let a=project(x[parents[j]]),b=project(x[j]);let limb=names[j][0],colors={A:'#e6a187',B:'#76cbd0',C:'#e3c27d',D:'#a6cf8d'};ctx.strokeStyle=colors[limb]||'#dce6df';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();ctx.beginPath();ctx.arc(...b,5,0,Math.PI*2);ctx.fillStyle=ctx.strokeStyle;ctx.fill()}}requestAnimationFrame(draw)}select();requestAnimationFrame(draw);</script>'''
 (p/'viewer.html').write_text(template.replace('DATA',json.dumps(data)).replace('PARENTS',json.dumps(d['parents'])).replace('NAMES',json.dumps(d['names'])))
 print('ATLAS',len(data),'clips',flush=True)
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('directory',type=Path);main(a.parse_args().directory)
